import { DashButton, Steps, TabItem, Tabs, WranglerConfig } from "~/components";
import SchemaDisplay from "~/components/models/SchemaDisplay.astro";

export const sharedInputProperties = {
	query: {
		type: "string",
		description: "The search query.",
		minLength: 1,
		maxLength: 1024,
	},
	provider: {
		type: "string",
		description: "The search provider to use.",
		enum: ["ceramic", "exa", "linkup"],
		default: "ceramic",
	},
	limit: {
		type: "integer",
		description: "The maximum number of search results to return.",
		minimum: 1,
		maximum: 10,
		default: 10,
	},
	byokAlias: {
		type: "string",
		description:
			"The alias of a provider API key stored on your gateway. If set, the request fails instead of falling back to AI Gateway credits when the key is not configured.",
		pattern: "^[A-Za-z0-9_-]{1,64}$",
	},
};

export const restInputSchema = {
	type: "object",
	properties: {
		query: sharedInputProperties.query,
		provider: sharedInputProperties.provider,
		limit: sharedInputProperties.limit,
		byokAlias: sharedInputProperties.byokAlias,
		options: {
			type: "object",
			description: "Request options.",
			properties: {
				gateway: {
					type: "object",
					description: "The AI Gateway to route the request through.",
					properties: {
						id: {
							type: "string",
							description: "The ID of the AI Gateway.",
						},
					},
					required: ["id"],
				},
			},
			required: ["gateway"],
		},
	},
	required: ["query", "options"],
};

export const bindingInputSchema = {
	type: "object",
	properties: {
		gatewayId: {
			type: "string",
			description: "The ID of the AI Gateway to route the request through.",
		},
		query: sharedInputProperties.query,
		provider: sharedInputProperties.provider,
		limit: sharedInputProperties.limit,
		byokAlias: sharedInputProperties.byokAlias,
	},
	required: ["gatewayId", "query"],
};

export const outputSchema = {
	type: "object",
	properties: {
		items: {
			type: "array",
			description: "The search results.",
			items: {
				type: "object",
				properties: {
					url: { type: "string", description: "The URL of the result." },
					title: { type: "string", description: "The title of the page." },
					description: {
						type: "string",
						description: "A description or excerpt of the page.",
					},
					imageUrl: {
						type: "string",
						description: "An image associated with the page.",
					},
					faviconUrl: {
						type: "string",
						description: "The favicon of the site.",
					},
					lastModifiedDate: {
						type: "string",
						format: "date-time",
						description: "The date the page was last modified.",
					},
				},
				required: ["url", "title"],
			},
		},
		metadata: {
			type: "object",
			description: "Information about the request.",
			properties: {
				query: { type: "string", description: "The search query." },
				requestId: {
					type: "string",
					description: "A unique identifier for the request.",
				},
				latencyMs: {
					type: "number",
					description: "The request latency in milliseconds.",
				},
			},
		},
	},
};

You can call Web Search API from any backend with the REST API, or from a Worker with the AI binding. Both methods route requests through an [AI Gateway](/ai-gateway/).

## Prerequisites

- A Cloudflare account. If you do not have one, [sign up](https://dash.cloudflare.com/sign-up).
- An AI Gateway. Every account has a gateway named `default`, or you can [create a gateway](/ai-gateway/get-started/).
- [AI Gateway credits](/ai-gateway/features/unified-billing/#load-credits) loaded on your account, or a [provider API key](#bring-your-own-key-byok) stored on your gateway.

## REST API

Send a `POST` request to the `/ai/websearch/` endpoint:

```txt
POST https://api.cloudflare.com/client/v4/accounts/{account_id}/ai/websearch/
```

Authenticate with a [Cloudflare API token](/fundamentals/api/get-started/create-token/) that has both of the following permissions:

- **Account** > **Workers AI** > **Read**
- **Account** > **AI Gateway** > **Read**

```bash
curl https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/ai/websearch/ \
  --request POST \
  --header "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
  --header "Content-Type: application/json" \
  --data '{
    "query": "What are some fun things to do in Salt Lake City as fall approaches?",
    "provider": "ceramic",
    "limit": 5,
    "options": {
      "gateway": { "id": "default" }
    }
  }'
```

## Workers binding

Call Web Search API from a Worker with the `websearch()` method on the [AI binding](/workers-ai/configuration/bindings/).

<Steps>

1. Add an AI binding to your Wrangler configuration file:

   <WranglerConfig>

   ```toml
   name = "web-search-worker"
   main = "src/index.ts"
   compatibility_date = "$today"

   [ai]
   binding = "AI"
   ```

   </WranglerConfig>

2. Call `env.AI.websearch()` with your gateway ID and query:

   ```ts title="src/index.ts"
   export default {
   	async fetch(request, env): Promise<Response> {
   		const response = await env.AI.websearch({
   			gatewayId: "default",
   			query:
   				"What are some fun things to do in Salt Lake City as fall approaches?",
   			provider: "exa",
   			limit: 5,
   		});

   		const results = await response.json();
   		return Response.json(results);
   	},
   } satisfies ExportedHandler<Env>;
   ```

</Steps>

`websearch()` returns a standard `Response` object. Call `response.json()` to read the results.

## Request parameters

Set `provider` to choose a [search provider](/web-search/providers/). If you do not set a provider, Web Search API uses Ceramic.ai as default.

<Tabs syncKey="webSearchMethod">
<TabItem label="REST API">

```json
{
	"query": "What are some fun things to do in Salt Lake City as fall approaches?",
	"provider": "ceramic",
	"limit": 5,
	"options": {
		"gateway": { "id": "default" }
	}
}
```

<SchemaDisplay schema={restInputSchema} hideSearch title="Input" />

</TabItem>
<TabItem label="Workers binding">

```ts
const response = await env.AI.websearch({
	gatewayId: "default",
	query: "What are some fun things to do in Salt Lake City as fall approaches?",
	provider: "ceramic",
	limit: 5,
});
```

<SchemaDisplay schema={bindingInputSchema} hideSearch title="Input" />

</TabItem>
</Tabs>

## Response format

```json
{
	"items": [
		{
			"url": "https://example.com/salt-lake-city-fall-guide",
			"title": "Fall in Salt Lake City: A Local's Guide",
			"description": "From scenic drives up Big Cottonwood Canyon to pumpkin patches..."
		}
	],
	"metadata": {
		"query": "What are some fun things to do in Salt Lake City as fall approaches?",
		"requestId": "<REQUEST_ID>",
		"latencyMs": 612
	}
}
```

<SchemaDisplay schema={outputSchema} hideSearch title="Output" />

Optional fields are only included when the provider returns them.

## Bring your own key (BYOK)

If you have an existing account with a search provider, you can use your own API key instead of AI Gateway credits. The provider bills you directly.

<Steps>

1. In the Cloudflare dashboard, go to the **AI Gateway** page.

   <DashButton url="/?to=/:account/ai/ai-gateway" />

2. Select your gateway, then select **Provider Keys**.
3. Add an API key for Ceramic.ai, Exa, or Linkup, and assign it an alias — for example, `default`. If the provider is not listed, select **Configure custom providers** to add it.
4. Pass the provider and alias in your request.

</Steps>

<Tabs syncKey="webSearchMethod">
<TabItem label="REST API">

```bash
curl https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/ai/websearch/ \
  --request POST \
  --header "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
  --header "Content-Type: application/json" \
  --data '{
    "query": "What is Cloudflare Workers?",
    "provider": "exa",
    "byokAlias": "default",
    "options": {
      "gateway": { "id": "default" }
    }
  }'
```

</TabItem>
<TabItem label="Workers binding">

```ts
const response = await env.AI.websearch({
	gatewayId: "default",
	query: "What is Cloudflare Workers?",
	provider: "exa",
	byokAlias: "default",
});
```

</TabItem>
</Tabs>

Your API key is never sent in the request. AI Gateway retrieves the key stored on the gateway for the provider and alias, and encrypts stored keys with [Secrets Store](/secrets-store/).

AI Gateway selects credentials as follows:

- **You set `byokAlias`** — AI Gateway uses the stored key with that alias. If the provider or alias is not configured on the gateway, the request fails with a `400` error instead of falling back to your credits.
- **You omit `byokAlias`** — If the gateway has a stored key with the `default` alias for the provider, AI Gateway uses that key. Otherwise, the search is billed to your AI Gateway credits.

For more information, refer to [Bring your own keys](/ai-gateway/configuration/bring-your-own-keys/).

## Use web search as a tool

You can give a model access to web search by defining a `web_search` tool. When the model calls the tool, run the search and pass the results back to the model.

```ts title="src/index.ts"
const MODEL = "@cf/google/gemma-4-26b-a4b-it";

export default {
	async fetch(request, env): Promise<Response> {
		const prompt = "What happened during the last Cloudflare Birthday Week?";
		const messages = [{ role: "user", content: prompt }];

		const completion = await env.AI.run(
			MODEL,
			{
				messages,
				tools: [
					{
						type: "function",
						function: {
							name: "web_search",
							description: "Search the web for current information.",
							parameters: {
								type: "object",
								properties: { query: { type: "string" } },
								required: ["query"],
							},
						},
					},
				],
			},
			{ gateway: { id: "default" } },
		);

		const toolCall = completion.tool_calls?.[0];
		if (toolCall?.name !== "web_search") {
			return Response.json(completion);
		}

		const searchResponse = await env.AI.websearch({
			gatewayId: "default",
			query: toolCall.arguments.query,
			limit: 5,
		});
		const searchResults = await searchResponse.json();

		const finalResponse = await env.AI.run(
			MODEL,
			{
				messages: [
					...messages,
					{
						role: "tool",
						name: "web_search",
						content: JSON.stringify(searchResults),
					},
				],
			},
			{ gateway: { id: "default" } },
		);

		return Response.json(finalResponse);
	},
} satisfies ExportedHandler<Env>;
```

## Limits

| Limit               | Value            |
| ------------------- | ---------------- |
| Query length        | 1,024 characters |
| Results per request | 10               |
